'use strict';
const KEY='studytracker_v1';
const colors=['#e97812','#dba563','#87b4a1','#b09dbe','#d59a89'];
const defaults=()=>({modules:[{id:'m1',name:'Mathematik',color:colors[0],goal:6},{id:'m2',name:'Technische Mechanik',color:colors[1],goal:5},{id:'m3',name:'Werkstoffkunde',color:colors[2],goal:3},{id:'m4',name:'Konstruktion',color:colors[3],goal:4}],topics:[],entries:[]});
function readData(){try{const d=JSON.parse(localStorage.getItem(KEY));if(d&&Array.isArray(d.modules)&&Array.isArray(d.topics)&&Array.isArray(d.entries))return d;}catch(e){}return defaults()}
let db=readData();const $=id=>document.getElementById(id);const fmt=n=>Number(n).toLocaleString('de-DE',{maximumFractionDigits:1});const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const uid=()=>typeof crypto!=='undefined'&&crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2);const getM=id=>db.modules.find(m=>m.id===id);const getT=id=>db.topics.find(t=>t.id===id);const dayKey=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;const today=()=>dayKey(new Date());const dateOf=s=>new Date(s+'T12:00:00');const startWeek=()=>{const d=dateOf(today());d.setDate(d.getDate()-(d.getDay()+6)%7);return dayKey(d)};const sum=entries=>entries.reduce((s,e)=>s+e.minutes,0);const hr=min=>fmt(min/60)+' h';
const notify=msg=>{document.querySelector('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.textContent=msg;document.body.append(el);setTimeout(()=>el.remove(),3000)};


const SEMESTERS=[
 {id:'ws-2026',label:'Wintersemester 2026/27',start:'2026-10-01',end:'2027-03-31'},
 {id:'ss-2027',label:'Sommersemester 2027',start:'2027-04-01',end:'2027-09-30'},
 {id:'ws-2027',label:'Wintersemester 2027/28',start:'2027-10-01',end:'2028-03-31'},
 {id:'ss-2028',label:'Sommersemester 2028',start:'2028-04-01',end:'2028-09-30'},
 {id:'ws-2028',label:'Wintersemester 2028/29',start:'2028-10-01',end:'2029-03-31'}
];
const LEGACY_TERM='ws-2026';
function studyRoot(){if(!db.study||typeof db.study!=='object'||Array.isArray(db.study))db.study={modules:[],events:[],tasks:[]};return db.study}
function activeTermId(){const id=db.study?.activeTermId;return SEMESTERS.some(t=>t.id===id)?id:LEGACY_TERM}
function activeTerm(){return SEMESTERS.find(t=>t.id===activeTermId())||SEMESTERS[0]}
function isTermDate(date){const t=activeTerm();return date>=t.start&&date<=t.end}
function termModules(){const id=activeTermId();return db.modules.filter(m=>(m.semesterId||LEGACY_TERM)===id)}
function termEntries(){const ids=new Set(termModules().map(m=>m.id));return db.entries.filter(e=>ids.has(e.moduleId))}
function termPlan(create=true){
 const root=create?studyRoot():db.study;if(!root||typeof root!=='object')return null;
 if(activeTermId()===LEGACY_TERM)return root;
 if(!root.termPlans){if(!create)return null;root.termPlans={}}
 let plan=root.termPlans[activeTermId()];
 if(!plan&&create)plan=root.termPlans[activeTermId()]={modules:[],events:[],tasks:[]};
 return plan||null;
}
function termSelectRender(){
 for(const id of ['topicsSemester','studySemester','plannerSemester']){
  const sel=$(id);if(!sel)continue;
  sel.innerHTML=SEMESTERS.map(t=>'<option value="'+esc(t.id)+'">'+esc(t.label)+'</option>').join('');
  sel.value=activeTermId();
 }
 const term=activeTerm();
 if($('dashboardSemesterLabel'))$('dashboardSemesterLabel').textContent='Auswertung für '+term.label;
 if($('semHeading'))$('semHeading').textContent='Studienplan · '+term.label;
 if($('semImport')){$('semImport').disabled=activeTermId()!==LEGACY_TERM;$('semImport').title=activeTermId()===LEGACY_TERM?'Modulhandbuch und Stundenplan importieren':'Der hinterlegte Stundenplan gilt nur für das Wintersemester 2026/27'}
}
function changeTerm(next){
 if(!SEMESTERS.some(t=>t.id===next)||next===activeTermId())return;
 if(timer.running){alert('Bitte zuerst den Lerntimer beenden, bevor du das Semester wechselst.');termSelectRender();return}
 studyRoot().activeTermId=next;
 const term=activeTerm();semView=dateOf(term.start);semSelected=term.start;plannerOffset=0;selectedDetailId='';
 if(editingTaskId)endTaskEdit();
 $('taskDate').value=isTermDate(today())?today():term.start;
 persist();notify(term.label+' ausgewählt');
}
for(const id of ['topicsSemester','studySemester','plannerSemester'])$(id).addEventListener('change',e=>changeTerm(e.target.value));

let editDialogCallback=null;
function openNameDialog({title,label='Neuer Name',value='',maxLength=100,submit='Umbenennen',type='text',min,max,onSave}){
 const dlg=$('appEditDialog'),field=$('appEditInput');
 $('appEditTitle').textContent=title;$('appEditLabel').textContent=label;$('appEditSave').textContent=submit;
 field.type=type;if(type==='text')field.maxLength=maxLength;else field.removeAttribute('maxlength');field.value=String(value);
 if(type==='number'){field.min=String(min??0);field.max=String(max??168);field.step='0.5'}else{field.removeAttribute('min');field.removeAttribute('max');field.removeAttribute('step')}
 $('appEditError').textContent='';editDialogCallback=onSave;
 dlg.showModal();requestAnimationFrame(()=>{field.focus();field.select()});
}
$('appEditForm').addEventListener('submit',e=>{
 e.preventDefault();const field=$('appEditInput'),value=field.value.trim();
 if(!value||!field.checkValidity()){$('appEditError').textContent='Bitte einen gültigen Wert eingeben.';field.focus();return}
 if(!editDialogCallback)return;
 const save=editDialogCallback;editDialogCallback=null;$('appEditDialog').close();save(value);
});
$('appEditClose').addEventListener('click',()=>$('appEditDialog').close());
$('appEditCancel').addEventListener('click',()=>$('appEditDialog').close());
$('appEditDialog').addEventListener('close',()=>{editDialogCallback=null});

function persist(){try{localStorage.setItem(KEY,JSON.stringify(db))}catch(e){alert('Speicherfehler: Bitte exportiere deine Daten.')}render();cloudChanged()}
function selectOptions(id,extra=[]){const el=$(id);const prev=el.value;el.innerHTML=extra.map(([v,n])=>`<option value="${esc(v)}">${esc(n)}</option>`).join('')+termModules().map(m=>`<option value="${esc(m.id)}">${esc(m.name)}</option>`).join('');if([...el.options].some(x=>x.value===prev))el.value=prev}
function topicOptions(modSelect,topicSelect){const m=$(modSelect).value;const el=$(topicSelect);const prev=el.value;el.innerHTML='<option value="">Kein Thema</option>'+db.topics.filter(t=>t.moduleId===m).map(t=>`<option value="${esc(t.id)}">${esc(t.parentId?"↳ ":"")}${esc(t.name)}</option>`).join('');if([...el.options].some(x=>x.value===prev))el.value=prev}
const getStats=()=>{const week=startWeek(),entries=termEntries();return {today:entries.filter(e=>e.date===today()),week:entries.filter(e=>e.date>=week&&e.date<=today()),all:entries}};
function drawOverview(){const stats=getStats();[['today','today'],['week','week'],['total','all']].forEach(([prefix,key])=>{$(prefix+'Metric').textContent=hr(sum(stats[key]));$(prefix+'Count').textContent=stats[key].length+' Lerneinheiten'});$('today').textContent=new Date().toLocaleDateString('de-DE',{weekday:'long',day:'numeric',month:'long',year:'numeric'});
const weekStats=stats.week;const totalByModule=termModules().map(m=>({...m,minutes:sum(termEntries().filter(e=>e.moduleId===m.id)),wMinutes:sum(weekStats.filter(e=>e.moduleId===m.id))}));const max=Math.max(1,...totalByModule.map(m=>m.minutes));$('moduleOverview').innerHTML=totalByModule.length?totalByModule.map(m=>`<div class="module-row" style="display:block"><div style="display:flex;justify-content:space-between;gap:9px"><span class="module-name"><i class="dot" style="background:${m.color}"></i>${esc(m.name)}</span><strong>${hr(m.minutes)}</strong></div><div class="bar"><div style="background:${m.color};width:${m.minutes/max*100}%"></div></div></div>`).join(''):'<div class="empty">Lege dein erstes Modul an.</div>';
$('goalOverview').innerHTML=totalByModule.filter(m=>m.goal>0).map(m=>`<div class="goal"><div class="goal-head"><span class="goal-title">${esc(m.name)}</span><span class="muted">${hr(m.wMinutes)} / ${fmt(m.goal)} h</span></div><div class="progress"><div style="width:${Math.min(100,m.wMinutes/(m.goal*60)*100)}%"></div></div></div>`).join('')||'<div class="empty">Keine Wochenziele vorhanden.</div>';
const lastDays=Array.from({length:7},(_,i)=>{const d=dateOf(today());d.setDate(d.getDate()-6+i);return{date:dayKey(d),label:d.toLocaleDateString('de-DE',{weekday:'short'}),minutes:sum(termEntries().filter(e=>e.date===dayKey(d)))}});const barmax=Math.max(60,...lastDays.map(d=>d.minutes));$('weekChart').innerHTML=lastDays.map(d=>`<div class="chart-item"><div class="small" style="margin-bottom:4px">${d.minutes?fmt(d.minutes/60):''}</div><div class="chart-bar-container"><div class="chart-bar" style="height:${Math.max(2,100*d.minutes/barmax)}%"></div></div>${esc(d.label)}</div>`).join('');
$('recentEntries').innerHTML=termEntries().length?sortEntries(termEntries()).slice(0,4).map(entryHtml).join(''):'<div class="empty">Noch keine Lerneinheiten erfasst. Starte deinen ersten Timer!</div>';
}
function sortEntries(a){return [...a].sort((x,y)=>((y.date||'')+' '+(y.createdAt||'')).localeCompare((x.date||'')+' '+(x.createdAt||'')))}
function entryHtml(e){return `<div class="entry"><div><strong>${esc(getM(e.moduleId)?.name||'Gelöschtes Modul')}${getT(e.topicId)?' · '+esc(getT(e.topicId).name):''}</strong><div class="muted">${esc(dateOf(e.date).toLocaleDateString('de-DE'))}${e.note?' · '+esc(e.note):''}</div></div><div class="right"><strong>${hr(e.minutes)}</strong><button class="icon-button" title="Eintrag löschen" data-delete-entry="${esc(e.id)}">×</button></div></div>`}
function drawTopics(){$('moduleList').innerHTML=termModules().map(m=>`<div class="module-row"><div><span class="module-name"><i class="dot" style="background:${m.color}"></i>${esc(m.name)}</span><span class="small muted">Wochenziel: ${fmt(m.goal)} h</span></div><div class="actions"><button class="icon-button" data-rename-module="${esc(m.id)}" title="Modul umbenennen">✎</button><button class="icon-button" data-edit-module="${esc(m.id)}" title="Wochenziel bearbeiten">Ziel</button><button class="icon-button" data-delete-module="${esc(m.id)}" title="Modul löschen">×</button></div></div>`).join('')||'<div class="empty">Noch keine Module.</div>';
const filter=$('topicListModule').value,visible=termModules().filter(m=>!filter||m.id===filter),matched=db.topics.filter(t=>visible.some(m=>m.id===t.moduleId));$('topicCount').textContent=matched.length+' Themen';$('topicList').innerHTML=matched.length?visible.map(m=>{const a=db.topics.filter(t=>t.moduleId===m.id);return a.length?`<div style="margin-bottom:15px"><div class="module-name"><i class="dot" style="background:${m.color}"></i>${esc(m.name)}</div>${a.map(t=>`<div class="topic ${t.parentId?'topic-indent':''}"><div class="topic-top"><span class="topic-title">${t.parentId?'↳ ':''}${esc(t.name)}</span><span class="topic-tools"><span class="chip">${hr(sum(db.entries.filter(e=>e.topicId===t.id)))}</span><button class="icon-button" data-edit-topic="${esc(t.id)}" title="Thema umbenennen">✎</button><button class="icon-button" data-delete-topic="${esc(t.id)}" title="Thema löschen">×</button></span></div><div class="field" style="margin-top:10px"><label>Kenntnisstand</label><select data-mastery="${esc(t.id)}">${['Noch nicht begonnen','Unsicher','In Bearbeitung','Gut verstanden','Sicher beherrscht'].map((label,i)=>`<option value="${i}" ${t.mastery===i?'selected':''}>${label}</option>`).join('')}</select></div></div>`).join('')}</div>`:''}).join(''):'<div class="empty">Füge Themen hinzu und bewerte deinen Lernfortschritt.</div>'}
function filteredEntries(moduleId,topicId,period){return sortEntries(termEntries()).filter(e=>(!moduleId||e.moduleId===moduleId)&&(!topicId||e.topicId===topicId)&&(period==='all'||(period==='week'?e.date>=startWeek()&&e.date<=today():e.date>=today().slice(0,7)+'-01'&&e.date<=today())))}
function drawHistorySemi(entries){
 const host=$('historySemiChart');host.replaceChildren();
 const byModule=new Map();
 for(const entry of entries){const minutes=Math.max(0,Number(entry.minutes)||0);if(!minutes)continue;const id=entry.moduleId||'unknown';byModule.set(id,(byModule.get(id)||0)+minutes)}
 const pieces=[...byModule].map(([id,minutes])=>({id,name:getM(id)?.name||'Ohne Modul',minutes})).sort((a,b)=>b.minutes-a.minutes);
 const total=pieces.reduce((n,item)=>n+item.minutes,0);
 $('historyVizSummary').textContent=total?hr(total)+' gesamt':'0 h';
 if(!total){const empty=document.createElement('p');empty.className='sub';empty.textContent='Für den gewählten Zeitraum sind noch keine Lernzeiten erfasst.';host.append(empty);return}
 const palette=['#ee7d22','#eab264','#80b7a1','#cfa18c','#b9a3d1','#91b2c8','#e2c878','#b1aba2'];
 const ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg');
 svg.setAttribute('viewBox','0 0 320 180');svg.setAttribute('role','img');
 svg.setAttribute('aria-label','Halbringdiagramm: '+pieces.map(p=>p.name+' '+hr(p.minutes)).join(', '));
 const add=(tag,attrs,parent=svg)=>{const e=document.createElementNS(ns,tag);for(const [k,v] of Object.entries(attrs))e.setAttribute(k,String(v));parent.append(e);return e};
 const x=angle=>160+126*Math.cos(angle),y=angle=>160-126*Math.sin(angle);
 add('path',{d:'M 34 160 A 126 126 0 0 1 286 160',fill:'none',stroke:'#44403b','stroke-width':27,'stroke-linecap':'butt'});
 let consumed=0;
 pieces.forEach((part,index)=>{
  const portion=part.minutes/total,from=Math.PI*(1-consumed),to=Math.PI*(1-consumed-portion);consumed+=portion;
  const margin=Math.min(.008,(from-to)/9),a=from-margin,b=to+margin;
  if(a<=b)return;
  const d='M '+x(a).toFixed(2)+' '+y(a).toFixed(2)+' A 126 126 0 0 1 '+x(b).toFixed(2)+' '+y(b).toFixed(2);
  const arc=add('path',{d,fill:'none',stroke:palette[index%palette.length],'stroke-width':27,'stroke-linecap':'butt'});
  const title=add('title',{},arc);title.textContent=part.name+': '+hr(part.minutes)+' ('+fmt(portion*100)+' %)';
 });
 const center=add('text',{x:160,y:124,'text-anchor':'middle',fill:'#f4f0eb','font-size':31,'font-weight':750});center.textContent=hr(total);
 const caption=add('text',{x:160,y:147,'text-anchor':'middle',fill:'#bbb2a8','font-size':12});caption.textContent='Lernzeit gesamt';
 const legend=document.createElement('div');legend.className='st-history-legend';
 pieces.forEach((item,index)=>{const row=document.createElement('div');row.className='st-history-legend-row';const dot=document.createElement('span');dot.className='st-history-legend-dot';dot.style.background=palette[index%palette.length];const name=document.createElement('span');name.textContent=item.name;const value=document.createElement('strong');value.textContent=hr(item.minutes)+' · '+fmt(item.minutes/total*100)+' %';row.append(dot,name,value);legend.append(row)});
 host.append(svg,legend);
}
function drawHistory(){const entries=filteredEntries($('historyModule').value,$('historyTopic').value,$('historyPeriod').value);$('historyEntries').innerHTML=entries.length?entries.map(entryHtml).join(''):'<div class="empty">Keine passenden Lerneinheiten gefunden.</div>';drawHistorySemi(entries)}
function drawTopicStats(){const moduleId=$('statsModule').value,period=$('statsPeriod').value,entries=filteredEntries(moduleId,'',period),total=sum(entries),topics=db.topics.filter(t=>termModules().some(m=>m.id===t.moduleId)&&(!moduleId||t.moduleId===moduleId));let rows=topics.map(t=>({t,minutes:sum(entries.filter(e=>e.topicId===t.id))})).filter(o=>o.minutes>0).sort((a,b)=>b.minutes-a.minutes);const unattributed=sum(entries.filter(e=>!e.topicId||!getT(e.topicId)));if(unattributed)rows.push({t:{name:'Ohne Thema',moduleId:''},minutes:unattributed});$('topicStats').innerHTML=`<p class="sub">${hr(total)} erfasst · ${entries.length} Lerneinheiten · ${rows.length} Themen/Kategorien mit Zeit</p>`+(rows.length?`<div style="overflow-x:auto"><table class="stats-table"><thead><tr><th>Thema</th><th>Modul</th><th>Anteil</th><th>Zeit</th></tr></thead><tbody>${rows.map(({t,minutes})=>`<tr><td>${esc(t.name)}</td><td>${esc(getM(t.moduleId)?.name||'—')}</td><td>${fmt(total?minutes/total*100:0)} %</td><td><strong>${hr(minutes)}</strong></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Noch keine erfassten Lernzeiten in diesem Zeitraum.</div>')}
function parentOptions(){const el=$('parentTopic'),prev=el.value,moduleId=$('topicModule').value;el.innerHTML='<option value="">Hauptthema</option>'+db.topics.filter(t=>t.moduleId===moduleId&&!t.parentId).map(t=>`<option value="${esc(t.id)}">${esc(t.name)}</option>`).join('');if([...el.options].some(o=>o.value===prev))el.value=prev}
function historyTopicOptions(){const el=$('historyTopic'),prev=el.value,moduleId=$('historyModule').value;el.innerHTML='<option value="">Alle Themen</option>'+db.topics.filter(t=>termModules().some(m=>m.id===t.moduleId)&&(!moduleId||t.moduleId===moduleId)).map(t=>`<option value="${esc(t.id)}">${esc(t.name)}</option>`).join('');if([...el.options].some(o=>o.value===prev))el.value=prev}

