const TIMER_SESSION='studytracker_timer_v3_session';
try {const saved=JSON.parse(sessionStorage.getItem(TIMER_SESSION)||'null');if(saved&&saved.savedAt&&Date.now()-saved.savedAt<86400000&&Number.isFinite(saved.elapsed)&&saved.elapsed>=0){timer={running:!!saved.running,elapsed:saved.elapsed+(saved.running?Math.max(0,Date.now()-saved.savedAt):0),start:performance.now(),moduleId:saved.moduleId||null,topicId:saved.topicId||null};if(!timer.running)timer.start=null}}catch(_){sessionStorage.removeItem(TIMER_SESSION)}
function persistTimerSession(){if(timer.elapsed<=0&&!timer.running){sessionStorage.removeItem(TIMER_SESSION);return}sessionStorage.setItem(TIMER_SESSION,JSON.stringify({running:timer.running,elapsed:timerElapsed(),moduleId:timer.moduleId,topicId:timer.topicId,savedAt:Date.now()}))}
setInterval(persistTimerSession,2500);
window.addEventListener('pagehide',persistTimerSession);
const timerElapsed=()=>Math.max(0,timer.elapsed+(timer.running?performance.now()-timer.start:0));function tick(){const sec=Math.floor(timerElapsed()/1000),h=Math.floor(sec/3600),m=Math.floor(sec%3600/60),s=sec%60;$('clock').textContent=[h,m,s].map(n=>String(n).padStart(2,'0')).join(':');$('timerStatus').textContent=timer.running?'Läuft':timer.elapsed?'Pausiert':'Bereit';$('runningInfo').textContent=timer.running?'Konzentrier dich auf dein Lernthema.':timer.elapsed?'Pausiert – weiterlernen oder speichern.':'Bereit für deine nächste Lerneinheit?';$('startBtn').textContent=timer.elapsed?'▶ Fortsetzen':'▶ Starten';$('startBtn').disabled=timer.running||!db.modules.length;$('pauseBtn').disabled=!timer.running;$('finishBtn').disabled=timerElapsed()<1000;$('timerModule').disabled=timerElapsed()>0;$('timerTopic').disabled=timerElapsed()>0}function pauseTimer(){if(timer.running){timer.elapsed=timerElapsed();timer.running=false;timer.start=null}tick();persistTimerSession()}function resetTimer(){timer={running:false,elapsed:0,start:null,moduleId:null,topicId:null};sessionStorage.removeItem(TIMER_SESSION);tick()}$('startBtn').addEventListener('click',()=>{if(!timer.elapsed){timer.moduleId=$('timerModule').value;timer.topicId=$('timerTopic').value}timer.start=performance.now();timer.running=true;tick()});$('pauseBtn').addEventListener('click',pauseTimer);$('resetBtn').addEventListener('click',()=>{if(timerElapsed()>1000&&!confirm('Den aktuellen Timer ohne Speichern zurücksetzen?'))return;resetTimer()});$('finishBtn').addEventListener('click',()=>{pauseTimer();const mins=Math.max(1,Math.round(timer.elapsed/60000));if(!getM(timer.moduleId))return alert('Das Modul existiert nicht mehr.');db.entries.push({id:uid(),date:today(),moduleId:timer.moduleId,topicId:timer.topicId,note:'',minutes:mins,createdAt:new Date().toISOString()});resetTimer();persist();notify(`${mins} Minute(n) gespeichert`)});let timerRaf=null,renderedTimerSecond=-1;
function timerLoop(){timerRaf=null;const currentSecond=Math.floor(timerElapsed()/1000);if(currentSecond!==renderedTimerSecond){renderedTimerSecond=currentSecond;tick()}if(!document.hidden)timerRaf=requestAnimationFrame(timerLoop)}
document.addEventListener('visibilitychange',()=>{tick();if(document.hidden){if(timerRaf!==null)cancelAnimationFrame(timerRaf);timerRaf=null}else if(timerRaf===null)timerRaf=requestAnimationFrame(timerLoop)});timerRaf=requestAnimationFrame(timerLoop);window.addEventListener('beforeunload',e=>{if(timerElapsed()>1000){e.preventDefault();e.returnValue=''}});
$('exportBtn').addEventListener('click',()=>{const blob=new Blob([JSON.stringify({version:2,exportedAt:new Date().toISOString(),...db},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='studytracker-backup-'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});$('importFile').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;try{const data=JSON.parse(await file.text());if(!Array.isArray(data.modules)||!Array.isArray(data.topics)||!Array.isArray(data.entries)||data.modules.some(m=>typeof m.id!=='string'||typeof m.name!=='string'||!/^#[0-9a-fA-F]{6}$/.test(m.color)||typeof m.goal!=='number')||data.entries.some(x=>typeof x.minutes!=='number'||!/^\d{4}-\d\d-\d\d$/.test(x.date)))throw Error('Ungültiges Backup');if(confirm('Alle aktuellen Daten mit diesem Backup ersetzen? Bitte sichere deine bisherigen Daten vorher.')){db={modules:data.modules,topics:data.topics,entries:data.entries,study:data.study||null};resetTimer();persist();notify('Backup importiert')}}catch(err){alert('Import fehlgeschlagen: '+err.message)}finally{e.target.value=''}});$('clearBtn').addEventListener('click',()=>{if(confirm('Wirklich ALLE Module, Themen und Lernzeiten löschen? Diese Aktion lässt sich nicht rückgängig machen.')){db={modules:[],topics:[],entries:[],study:null};resetTimer();persist();notify('Alle Daten gelöscht')}});


