let semView=new Date(2026,9,1),semSelected='2026-10-15';

function eventKind(e){
 if(['exam','lecture','exercise','tutorial','practical','coaching'].includes(e.kind))return e.kind;
 const n=String(e.name||'').toLowerCase();
 if(/prüfung|klausur|exam/.test(n))return 'exam';
 if(/tutorium|tutorien/.test(n))return 'tutorial';
 if(/übung|uebung/.test(n))return 'exercise';
 if(/praktikum|labor|laborkurs/.test(n))return 'practical';
 if(/coaching/.test(n))return 'coaching';
 return 'lecture';
}
function taskKind(t){return t.kind==='exam'?'exam':t.kind==='study'?'study':'task'}
const EVENT_LABELS={exam:'Prüfung',lecture:'Vorlesung',exercise:'Übung',tutorial:'Tutorium',practical:'Praktikum',coaching:'Coaching',task:'Aufgabe',study:'Lernblock'};
function eventLabel(kind){return EVENT_LABELS[kind]||'Veranstaltung'}
function eventLegend(){return '<div class="calendar-legend" aria-label="Legende der Veranstaltungstypen">'+Object.entries(EVENT_LABELS).map(([k,v])=>`<span class="event-pill ev-${k}">${v}</span>`).join('')+'</div>'}

function semData(){const plan=termPlan(false);return plan&&Array.isArray(plan.modules)&&Array.isArray(plan.events)?plan:null}
function semModuleId(ref){const meta=semData()?.modules.find(m=>m.id===ref);return meta?.localId||null}
function semTime(e){const a=e.start.split(':').map(Number),b=e.end.split(':').map(Number);return (b[0]*60+b[1])-(a[0]*60+a[1])}
function drawSemester(){
 const study=semData();const rows=study?.modules||(activeTermId()===LEGACY_TERM?HANDBOOK_MODULES:[]);const term=activeTerm();if(!isTermDate(dayKey(semView))){semView=dateOf(term.start);semSelected=term.start}
 $('semStatus').textContent=study?`${study.events.length} Plantermine · ${rows.length} Studienmodule · ${term.label}.`:(activeTermId()===LEGACY_TERM?`Bereit zum Import: ${SCHEDULE.length} Plantermine und ${HANDBOOK_MODULES.length} Module.`:'Noch kein Stundenplan hinterlegt. Lege Module und Termine für dieses Semester separat an.');
 $('semWork').innerHTML=rows.map(m=>{let mins=sum(termEntries().filter(e=>e.moduleId===(m.localId||semModuleId(m.id))));const remainder=Math.max(0,(Number(m.self)||0)-mins/60);return `<tr><td>${esc(m.name)}</td><td>${m.ects}</td><td>${m.total} h</td><td>${m.presence} h</td><td>${m.self} h</td><td>${hr(mins)}</td><td>${fmt(remainder)} h</td></tr>`}).join('')||'<tr><td colspan="7">Noch keine Module für dieses Semester angelegt.</td></tr>';
 $('semMonth').textContent=semView.toLocaleDateString('de-DE',{month:'long',year:'numeric'});
 const year=semView.getFullYear(),month=semView.getMonth(),first=new Date(year,month,1),offset=(first.getDay()+6)%7;
 let html='';for(let i=0;i<42;i++){let d=new Date(year,month,1-offset+i),date=dayKey(d),events=(study?.events||[]).filter(e=>e.date===date),entries=termEntries().filter(e=>e.date===date),tasks=(study?.tasks||[]).filter(t=>t.date===date),here=d.getMonth()===month,within=isTermDate(date);
 const tags=[...new Set(events.map(eventKind))].map(k=>{const count=events.filter(e=>eventKind(e)===k).length;return `<span class="sem-tag ev-${k}" title="${count} × ${eventLabel(k)}"><span class="sem-tag-label">${count}× ${eventLabel(k)}</span><span class="sem-tag-compact" aria-hidden="true">${count}</span></span>`}).concat(entries.length?[`<span class="sem-tag sem-learn" title="${hr(sum(entries))} gelernt"><span class="sem-tag-label">${hr(sum(entries))} gelernt</span><span class="sem-tag-compact" aria-hidden="true">✓</span></span>`]:[],[...new Set(tasks.map(taskKind))].map(k=>{const count=tasks.filter(t=>taskKind(t)===k).length;return `<span class="sem-tag ev-${k}" title="${count} × ${eventLabel(k)}"><span class="sem-tag-label">${count}× ${eventLabel(k)}</span><span class="sem-tag-compact" aria-hidden="true">${count}</span></span>`}));
 html+=`<button type="button" class="sem-day ${here?'':'muted-day'} ${within?'':'sem-outside'} ${date===semSelected?'focus':''}" data-semdate="${date}" ${within?'':'disabled'} aria-label="${esc(d.toLocaleDateString('de-DE',{day:'numeric',month:'long',year:'numeric'}))}: ${tags.length} Ereignistypen"><strong>${d.getDate()}</strong><div class="small">${within?tags.join(''):''}</div></button>`}
 $('semCalendar').innerHTML=html;$('semPrev').disabled=year===Number(term.start.slice(0,4))&&month===Number(term.start.slice(5,7))-1;$('semNext').disabled=year===Number(term.end.slice(0,4))&&month===Number(term.end.slice(5,7))-1; if(!$('semCalendar').previousElementSibling?.classList.contains('calendar-legend'))$('semCalendar').insertAdjacentHTML('beforebegin',eventLegend());
 const ds=dateOf(semSelected);$('semDayTitle').textContent=ds.toLocaleDateString('de-DE',{weekday:'long',day:'numeric',month:'long',year:'numeric'});
 const events=(study?.events||[]).filter(e=>e.date===semSelected).sort((a,b)=>a.start.localeCompare(b.start));const entries=termEntries().filter(e=>e.date===semSelected);const dayTasks=(study?.tasks||[]).filter(t=>t.date===semSelected);
 $('semDayDetail').innerHTML=(events.map(e=>`<div class="sem-event ev-${eventKind(e)}"><span class="event-pill ev-${eventKind(e)}">${eventLabel(eventKind(e))}</span><b>${esc(e.start)}–${esc(e.end)} · ${esc(e.name)}</b><span class="sub">Geplant · ${esc(e.details||'')}</span></div>`).join('')+entries.map(e=>`<div class="sem-event ev-study"><b>Selbststudium · ${esc(getM(e.moduleId)?.name||'Modul')}</b><span class="sub">${hr(e.minutes)}${e.note?' · '+esc(e.note):''}</span></div>`).join('')+dayTasks.map(t=>`<div class="sem-event ev-${taskKind(t)}"><b>${esc(eventLabel(taskKind(t)))} · ${esc(t.title)}</b><span class="sub">${esc(t.time||'Ganztägig')} · ${esc(getM(t.moduleId)?.name||'Ohne Modul')}${t.done?' · Erledigt':''}</span></div>`).join(''))||'<p class="sub">Keine Veranstaltungen oder Lernzeiten eingetragen.</p>';
}
$('semImport').addEventListener('click',()=>{
 if(activeTermId()!==LEGACY_TERM)return;if(!confirm('Module und Stundenplan aus den PDF-Quellen importieren? Vorher ein JSON-Backup exportieren. Bestehende Lernzeiten bleiben bestehen.'))return;
 const existing=semData();let study={modules:HANDBOOK_MODULES.map(m=>({...m,localId:existing?.modules.find(x=>x.id===m.id)?.localId||''})),events:SCHEDULE.map(e=>({...e,kind:existing?.events?.find(x=>x.id===e.id)?.kind||eventKind(e)})),tasks:existing?.tasks||[]};
 for(let i=0;i<study.modules.length;i++){let m=study.modules[i];let old=db.modules.find(x=>x.id===m.localId)||termModules().find(x=>x.name.toLowerCase()===m.name.toLowerCase());
 if(!old){const aliases=[['mathematik','mathe'],['technische mechanik'],['werkstoff'],['naturwissenschaft'],['konstruktion'],['coaching']][i];old=termModules().find(x=>aliases.some(a=>x.name.toLowerCase().includes(a)));}
 if(!old){old={id:uid(),name:m.name,color:colors[i%colors.length],goal:4,semesterId:LEGACY_TERM};db.modules.push(old)}m.localId=old.id;
 }
 db.study=study;let added=0;for(const m of study.modules)added+=seedTopics(m.localId);persist();notify('Studienplan importiert · '+added+' Themen ergänzt');showTab('semester');
});
$('semPrev').addEventListener('click',()=>{semView=new Date(semView.getFullYear(),semView.getMonth()-1,1);drawSemester()});
$('semNext').addEventListener('click',()=>{semView=new Date(semView.getFullYear(),semView.getMonth()+1,1);drawSemester()});
$('semCalendar').addEventListener('click',e=>{let b=e.target.closest('[data-semdate]');if(!b)return;semSelected=b.dataset.semdate;drawSemester()});
$('semIcs').addEventListener('click',()=>{const ev=semData()?.events||(activeTermId()===LEGACY_TERM?SCHEDULE:[]);const safe=s=>String(s).replace(/[,;\r\n]/g,' ');const line=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//StudyTracker//WS26//DE','CALSCALE:GREGORIAN',...ev.flatMap(e=>['BEGIN:VEVENT','UID:'+e.id+'@studytracker.local','DTSTAMP:20261015T120000Z','DTSTART:'+e.date.replaceAll('-','')+'T'+e.start.replace(':','')+'00','DTEND:'+e.date.replaceAll('-','')+'T'+e.end.replace(':','')+'00','SUMMARY:'+safe(e.name),'DESCRIPTION:'+safe(e.details),'END:VEVENT']),'END:VCALENDAR'];const blob=new Blob([line.join('\r\n')+'\r\n'],{type:'text/calendar;charset=utf-8'});const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='StudyTracker-'+activeTermId()+'.ics';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)});

// StudyTracker 2.2 additions. Keep all data in existing db.study to preserve Railway API schema.
let plannerOffset=0;
function plannerStudy(){const plan=termPlan();if(!Array.isArray(plan.modules))plan.modules=[];if(!Array.isArray(plan.events))plan.events=[];if(!Array.isArray(plan.tasks))plan.tasks=[];return plan}
function plannerTasks(){return Array.isArray(termPlan(false)?.tasks)?termPlan(false).tasks:[]}
function mondayOffset(offset=0){const d=dateOf(isTermDate(today())?today():activeTerm().start);d.setDate(d.getDate()-(d.getDay()+6)%7+offset*7);return d}
function addDays(d,n){const x=new Date(d);x.setDate(x.getDate()+n);return x}
function taskName(t){return (t.kind==='exam'?'Prüfung':t.kind==='study'?'Lernblock':'Aufgabe')+' · '+t.title}
function plannerRender(){
 const monday=mondayOffset(plannerOffset),s=plannerStudy(),tasks=plannerTasks();
 $('planPrev').disabled=dayKey(addDays(monday,-1))<activeTerm().start;$('planNext').disabled=dayKey(addDays(monday,7))>activeTerm().end;$('planToday').textContent=isTermDate(today())?'Heute':'Semesterstart';
 $('planWeek').textContent=monday.toLocaleDateString('de-DE',{day:'2-digit',month:'2-digit'})+' – '+addDays(monday,6).toLocaleDateString('de-DE',{day:'2-digit',month:'2-digit',year:'numeric'});
 const select=$('taskModule'),old=select.value;select.innerHTML='<option value="">Ohne Modul</option>'+termModules().map(m=>`<option value="${esc(m.id)}">${esc(m.name)}</option>`).join('');if([...select.options].some(x=>x.value===old))select.value=old;
 let weekHtml='<div class="planweek">';for(let i=0;i<7;i++){
  const d=addDays(monday,i),date=dayKey(d),events=(s.events||[]).filter(e=>e.date===date).sort((a,b)=>a.start.localeCompare(b.start)),te=tasks.filter(t=>t.date===date).sort((a,b)=>(a.time||'').localeCompare(b.time||'')),en=termEntries().filter(e=>e.date===date);
  weekHtml+=`<div class="planday"><h3>${esc(d.toLocaleDateString('de-DE',{weekday:'short',day:'numeric',month:'numeric'}))}</h3>`;
  weekHtml+=events.map(e=>`<div class="planitem ev-${eventKind(e)}"><small>${eventLabel(eventKind(e))}</small>${esc(e.start)}–${esc(e.end)} ${esc(e.name)}</div>`).join('');
  weekHtml+=te.map(t=>`<div class="planitem ev-${taskKind(t)} ${t.done?'done':''}"><small>${eventLabel(taskKind(t))}</small>${esc(t.time||'')} ${esc(t.title)}</div>`).join('');
  if(en.length)weekHtml+=`<div class="planitem ev-study">✓ ${hr(sum(en))} selbst gelernt</div>`;
  weekHtml+='</div>';
 }$('planCalendar').innerHTML=weekHtml+'</div>';if(!$('planCalendar').previousElementSibling?.classList.contains('calendar-legend'))$('planCalendar').insertAdjacentHTML('beforebegin',eventLegend());
 const filter=$('taskFilter').value,shown=tasks.filter(t=>filter==='all'||filter==='open'&&t.kind==='task'&&!t.done||filter==='done'&&t.kind==='task'&&t.done||filter===t.kind).sort((a,b)=>(a.date+(a.time||'')).localeCompare(b.date+(b.time||'')));
 $('taskCount').textContent=tasks.filter(t=>t.kind==='task'&&!t.done).length+' offen';
 $('taskList').innerHTML=shown.length?shown.map(t=>`<div class="taskrow"><strong>${esc(taskName(t))}</strong><div class="sub small">${esc(t.date)} ${esc(t.time||'')} · ${esc(getM(t.moduleId)?.name||'Ohne Modul')} · ${esc(t.priority||'normal')}${t.minutes?' · '+t.minutes+' min geplant':''}</div>${t.note?`<p class="small">${esc(t.note)}</p>`:''}<div class="buttons">${t.kind==='task'?`<button data-task-toggle="${esc(t.id)}">${t.done?'↶ Wieder öffnen':'✓ Erledigt'}</button>`:''}<button data-task-rename="${esc(t.id)}">Umbenennen</button><button data-task-edit="${esc(t.id)}">Bearbeiten</button><button class="danger" data-task-delete="${esc(t.id)}">Löschen</button></div></div>`).join(''):'<div class="empty">Keine Einträge für diese Ansicht.</div>';
 const hrs=sum(termEntries())/60,assigned=s.modules||[],goal=assigned.reduce((v,m)=>v+(Number(m.self)||0),0);
 const start=dateOf(activeTerm().start),end=dateOf(activeTerm().end),timeProgress=Math.max(0,Math.min(1,(dateOf(today())-start)/(end-start)));
 let stat=`<div class="statsmini"><div><div class="sub">Selbst gelernt</div><div class="num">${fmt(hrs)} h</div></div><div><div class="sub">Selbststudium-Soll</div><div class="num">${goal?fmt(goal)+' h':'—'}</div></div><div><div class="sub">Zeitanteil Semester (Referenz)</div><div class="num">${fmt(timeProgress*100)} %</div></div></div>`;
 stat+=assigned.length?'<div style="overflow:auto"><table class="sem-table"><thead><tr><th>Modul</th><th>Selbststudium Soll</th><th>zeitanteilig</th><th>Ist gelernt</th><th>Differenz</th></tr></thead><tbody>'+assigned.map(m=>{const actual=sum(termEntries().filter(e=>e.moduleId===m.localId))/60,target=Number(m.self)||0,expected=target*timeProgress;return `<tr><td>${esc(m.name)}</td><td>${fmt(target)} h</td><td>${fmt(expected)} h</td><td>${fmt(actual)} h</td><td>${fmt(actual-expected)} h</td></tr>`}).join('')+'</tbody></table></div>':'<div class="empty">Importiere im Studienplan zuerst die Module aus dem Handbuch.</div>';
 $('planStats').innerHTML=stat;
 $('planOnlineStatus').textContent=navigator.onLine?'Online: lokale Daten verfügbar; Cloud-Status unter Daten & Einstellungen prüfen.':'Offline: neue Einträge werden lokal gespeichert und müssen später synchronisiert werden.';
}
$('taskDate').value=isTermDate(today())?today():activeTerm().start;
$('planPrev').addEventListener('click',()=>{plannerOffset--;plannerRender()});$('planNext').addEventListener('click',()=>{plannerOffset++;plannerRender()});$('planToday').addEventListener('click',()=>{plannerOffset=0;plannerRender()});$('taskFilter').addEventListener('change',plannerRender);
