function endTaskEdit(){editingTaskId=null;$('taskSubmit').textContent='+ Eintrag erstellen';$('taskCancel').classList.add('hidden');$('taskForm').reset();$('taskDate').value=isTermDate(today())?today():activeTerm().start}
