$('taskForm').addEventListener('submit',e=>{e.preventDefault();const title=$('taskTitle').value.trim(),date=$('taskDate').value;if(!title||!/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(date))return;if(!isTermDate(date)){alert('Datum muss innerhalb von '+activeTerm().label+' liegen ('+activeTerm().start+' bis '+activeTerm().end+').');return}const existing=editingTaskId?plannerTasks().find(x=>x.id===editingTaskId):null;const t={id:existing?.id||uid(),title:title.slice(0,140),kind:$('taskKind').value,moduleId:$('taskModule').value,date,time:$('taskTime').value,minutes:Number($('taskMinutes').value)||0,priority:$('taskPriority').value,note:$('taskNote').value.trim(),done:existing?.done||false,createdAt:existing?.createdAt||new Date().toISOString()};if(existing)Object.assign(existing,t);else plannerStudy().tasks.push(t);endTaskEdit();persist();notify(existing?'Eintrag aktualisiert':'Termin/Aufgabe gespeichert')});
document.addEventListener('click',e=>{const el=e.target.closest('[data-task-toggle],[data-task-delete],[data-task-edit],[data-task-rename]');if(!el)return;const id=el.dataset.taskToggle||el.dataset.taskDelete||el.dataset.taskEdit||el.dataset.taskRename,t=plannerTasks().find(x=>x.id===id);if(!t)return;if(el.dataset.taskRename){openNameDialog({title:'Umbenennen · Aufgabe',value:t.title,maxLength:140,onSave:name=>{t.title=name.slice(0,140);persist();notify('Aufgabe umbenannt')}});return}if(el.dataset.taskEdit){editingTaskId=t.id;$('taskTitle').value=t.title;$('taskKind').value=t.kind;$('taskModule').value=t.moduleId||'';$('taskDate').value=t.date;$('taskTime').value=t.time||'';$('taskMinutes').value=t.minutes||0;$('taskPriority').value=t.priority||'normal';$('taskNote').value=t.note||'';$('taskSubmit').textContent='Änderungen speichern';$('taskCancel').classList.remove('hidden');$('taskForm').scrollIntoView({behavior:'smooth',block:'center'});$('taskTitle').focus();return}if(el.dataset.taskDelete){if(!confirm('Eintrag löschen?'))return;plannerStudy().tasks=plannerTasks().filter(x=>x.id!==id)}else t.done=!t.done;persist()});
