// Version 2.4: Praxisphasen are metadata in the owner-only synced dataset.
function praxisStore(){if(!db.study||typeof db.study!=='object')db.study={};if(!Array.isArray(db.study.practicePhases))db.study.practicePhases=[];return db.study}
function safeLink(v){try{const u=new URL(v);return u.protocol==='https:'?u.href:''}catch{return ''}}
function drawPraxis(){const st=praxisStore(),list=$('phaseList');if(!list)return;$('reportLink').value=st.reportBookUrl||'';const link=safeLink(st.reportBookUrl);$('reportOpen').classList.toggle('hidden',!link);if(link)$('reportOpen').href=link;
 list.innerHTML=st.practicePhases.length?st.practicePhases.map(ph=>`<div class="card phase-card" data-phase="${esc(ph.id)}"><div class="title-row"><div><h2>${esc(ph.name)}</h2><div class="sub">${esc(ph.period||'Kein Zeitraum')}</div></div><button class="danger" data-phase-rename="${esc(ph.id)}" class="secondary">Umbenennen</button><button class="danger" data-phase-remove="${esc(ph.id)}">Löschen</button></div><details><summary>Praxisphase bearbeiten</summary><div class="stack" style="padding-top:12px"><div class="field"><label>Titel</label><input data-phase-name="${esc(ph.id)}" maxlength="120" value="${esc(ph.name)}"></div><div class="field"><label>Zeitraum</label><input data-phase-period="${esc(ph.id)}" maxlength="80" value="${esc(ph.period||'')}"></div><div class="field"><label>Beschreibung</label><textarea data-phase-desc="${esc(ph.id)}" maxlength="1500">${esc(ph.description||'')}</textarea></div><button class="secondary" data-phase-save="${esc(ph.id)}">Änderungen speichern</button></div></details><div class="divider"></div><h3>Protokolle, Berichte und Präsentationen</h3><div class="field"><label>Dokumenttitel</label><input id="assetTitle_${esc(ph.id)}" maxlength="120" placeholder="z. B. Wochenprotokoll 1"></div><div class="two"><div class="field"><label>Art</label><select id="assetType_${esc(ph.id)}"><option>Protokoll</option><option>Bericht</option><option>Präsentation</option><option>Berichtsheft</option><option>Sonstiges</option></select></div><div class="field"><label>Privater Link (optional)</label><input id="assetLink_${esc(ph.id)}" type="url" placeholder="https://..."></div></div><div class="field"><label>Datei auf diesem Gerät ablegen (optional)</label><input class="practice-file-input" type="file" id="assetFile_${esc(ph.id)}" accept=".pdf,.xlsx,.xls,.docx,.pptx,.txt,.csv,.png,.jpg,.jpeg"></div><div class="buttons" style="margin-top:9px"><button class="secondary" data-asset-add="${esc(ph.id)}">+ Dokument hinzufügen</button></div><p class="sub small">Dateianhänge bleiben lokal auf diesem Gerät. Nur Titel, Art und Links werden synchronisiert.</p><div class="practice-files">${(ph.assets||[]).map(a=>`<div class="practice-asset"><div><strong>${esc(a.title)}</strong><div class="sub small">${esc(a.type)} ${a.localFile?'· lokale Datei auf Ursprungsgerät':''}</div></div><div class="buttons">${safeLink(a.url)?`<a class="secondary" href="${esc(safeLink(a.url))}" target="_blank" rel="noopener noreferrer">Link ↗</a>`:''}${a.localFile?`<button class="secondary" data-asset-download="${esc(a.id)}">Datei</button>`:''}<button class="danger" data-asset-remove="${esc(a.id)}">×</button></div></div>`).join('')||'<p class="sub">Noch keine Dokumente angelegt.</p>'}</div></div>`).join(''):'<div class="empty">Noch keine Praxisphase. Lege oben deine erste an.</div>'}
$('phaseForm').addEventListener('submit',e=>{e.preventDefault();const name=$('phaseName').value.trim();if(!name)return;praxisStore().practicePhases.push({id:uid(),name:name.slice(0,120),period:$('phasePeriod').value.trim().slice(0,80),description:$('phaseDesc').value.trim().slice(0,1500),assets:[]});e.target.reset();persist();drawPraxis()});
$('reportForm').addEventListener('submit',e=>{e.preventDefault();const raw=$('reportLink').value.trim(),url=raw?safeLink(raw):'';if(raw&&!url)return alert('Bitte einen gültigen HTTPS-Link eingeben.');praxisStore().reportBookUrl=url;persist();drawPraxis();notify('Berichtsheft-Link gespeichert')});
$('reportPreview').addEventListener('click',()=>{const url=safeLink(praxisStore().reportBookUrl);if(!url)return alert('Bitte zuerst einen gültigen Link speichern.');const holder=$('reportFrameHolder');const show=holder.classList.contains('hidden');holder.classList.toggle('hidden',!show);$('reportFrame').src=show?url:'about:blank'});
// IndexedDB: local-only attachments. Never serialized into sync or JSON backups.
let fileDB;
function getFileDB(){if(fileDB)return fileDB;fileDB=new Promise((resolve,reject)=>{const r=indexedDB.open('StudyTrackerPraxisFiles',1);r.onupgradeneeded=()=>r.result.createObjectStore('files');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});return fileDB}
async function filePut(id,file){const d=await getFileDB();return new Promise((res,rej)=>{const tx=d.transaction('files','readwrite');tx.objectStore('files').put(file,id);tx.oncomplete=res;tx.onerror=()=>rej(tx.error)})}
async function fileGet(id){const d=await getFileDB();return new Promise((res,rej)=>{const r=d.transaction('files').objectStore('files').get(id);r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}
async function fileDel(id){const d=await getFileDB();return new Promise((res,rej)=>{const tx=d.transaction('files','readwrite');tx.objectStore('files').delete(id);tx.oncomplete=res;tx.onerror=()=>rej(tx.error)})}
$('phaseList').addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const p=praxisStore();const phaseId=b.dataset.phaseSave||b.dataset.phaseRemove||b.dataset.assetAdd||b.dataset.phaseRename;const phase=p.practicePhases.find(x=>x.id===phaseId);if(b.dataset.phaseRename&&phase){openNameDialog({title:'Umbenennen · Praxisphase',value:phase.name,maxLength:120,onSave:name=>{phase.name=name.slice(0,120);persist();drawPraxis();notify('Praxisphase umbenannt')}});return}if(b.dataset.phaseSave&&phase){phase.name=document.querySelector(`[data-phase-name="${CSS.escape(phaseId)}"]`).value.trim()||phase.name;phase.period=document.querySelector(`[data-phase-period="${CSS.escape(phaseId)}"]`).value.trim();phase.description=document.querySelector(`[data-phase-desc="${CSS.escape(phaseId)}"]`).value.trim();persist();drawPraxis();return}if(b.dataset.phaseRemove&&phase){if(!confirm('Praxisphase und alle Dokumentverweise löschen? Lokale Anhänge werden ebenfalls entfernt.'))return;for(const a of phase.assets||[])if(a.localFile)await fileDel(a.id).catch(()=>{});p.practicePhases=p.practicePhases.filter(x=>x.id!==phaseId);persist();drawPraxis();return}if(b.dataset.assetAdd&&phase){const name=$('assetTitle_'+phaseId).value.trim(),urlText=$('assetLink_'+phaseId).value.trim(),url=urlText?safeLink(urlText):'';const file=$('assetFile_'+phaseId).files[0];if(!name)return alert('Bitte einen Dokumenttitel eingeben.');if(urlText&&!url)return alert('Nur HTTPS-Links sind erlaubt.');if(file&&file.size>20*1024*1024)return alert('Maximal 20 MB je Datei für lokale Anhänge.');if(!file&&!url)return alert('Bitte einen Link oder eine Datei auswählen.');const id=uid();if(file){try{await filePut(id,file)}catch(err){return alert('Datei konnte lokal nicht gespeichert werden: '+err.message)}}if(!Array.isArray(phase.assets))phase.assets=[];phase.assets.push({id,title:name.slice(0,120),type:$('assetType_'+phaseId).value,url,localFile:!!file,fileName:file?.name||''});persist();drawPraxis();return}
const aId=b.dataset.assetRemove||b.dataset.assetDownload;if(!aId)return;const ph=p.practicePhases.find(x=>(x.assets||[]).some(a=>a.id===aId));const a=ph?.assets.find(x=>x.id===aId);if(!a)return;if(b.dataset.assetRemove){if(!confirm('Dokument entfernen?'))return;if(a.localFile)await fileDel(a.id).catch(()=>{});ph.assets=ph.assets.filter(x=>x.id!==aId);persist();drawPraxis()}else{const blob=await fileGet(a.id).catch(()=>null);if(!blob)return alert('Die Datei liegt nur auf dem Gerät, auf dem sie hochgeladen wurde.');const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=a.fileName||'Datei';link.click();setTimeout(()=>URL.revokeObjectURL(url),3000)}});
// Render praxis when tab is shown, and refresh after remote sync through existing render().
const originalRender=render;render=function(){originalRender();drawPraxis()};
const originalShowTab=showTab;showTab=function(id){originalShowTab(id);if(id==='practice')drawPraxis()};
// Full-screen focus overlay. Wall-clock based timing remains accurate if tabs are throttled.
function refreshFocus(){const ms=Math.max(0,timerElapsed()),sec=Math.floor(ms/1000),val=[Math.floor(sec/3600),Math.floor(sec%3600/60),sec%60].map(x=>String(x).padStart(2,'0')).join(':')+'.'+Math.floor(ms%1000/100);$('focusClock').textContent=val;$('focusState').textContent=$('timerStatus').textContent;$('focusSubject').textContent=getM(timer.moduleId||$('timerModule').value)?.name||'Kein Modul gewählt';$('focusStart').disabled=$('startBtn').disabled;$('focusPause').disabled=$('pauseBtn').disabled;$('focusFinish').disabled=$('finishBtn').disabled}
$('focusOpen').addEventListener('click',()=>{$('focusOverlay').classList.remove('hidden');document.body.style.overflow='hidden';refreshFocus();if($('focusOverlay').requestFullscreen&&document.fullscreenEnabled)$('focusOverlay').requestFullscreen().catch(()=>{})});
$('focusClose').addEventListener('click',()=>{$('focusOverlay').classList.add('hidden');document.body.style.overflow='';if(document.fullscreenElement)document.exitFullscreen().catch(()=>{})});
for(const [f,b] of [['focusStart','startBtn'],['focusPause','pauseBtn'],['focusFinish','finishBtn']])$(f).addEventListener('click',()=>{$(b).click();refreshFocus()});
function focusAnimation(){if(!$('focusOverlay').classList.contains('hidden'))refreshFocus();requestAnimationFrame(focusAnimation)}requestAnimationFrame(focusAnimation);
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('focusOverlay').classList.contains('hidden'))$('focusClose').click()});
